CREATE OR REPLACE FUNCTION public.guard_gym_action() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE a text; k text; g uuid; operation text; prior public.gym_records; BEGIN IF auth.uid() IS NULL THEN RETURN coalesce(NEW,OLD); END IF; k=coalesce(NEW.kind,OLD.kind); g=coalesce(NEW.gym_id,OLD.gym_id); a=CASE k WHEN 'gym' THEN 'Profile' WHEN 'members' THEN 'Members' WHEN 'plans' THEN 'Members' WHEN 'workouts' THEN 'Workout programs' WHEN 'trainers' THEN 'Workout programs' WHEN 'sessions' THEN 'Sessions' WHEN 'attendance' THEN 'Attendance' WHEN 'staffAttendance' THEN 'Attendance' WHEN 'products' THEN 'Products' ELSE 'Finance' END; operation=CASE TG_OP WHEN 'INSERT' THEN 'create' WHEN 'DELETE' THEN 'delete' ELSE 'edit' END; IF TG_OP='INSERT' THEN SELECT * INTO prior FROM public.gym_records WHERE gym_id=NEW.gym_id AND kind=NEW.kind AND id=NEW.id; IF FOUND THEN IF prior.data IS NOT DISTINCT FROM NEW.data AND prior.client_id IS NOT DISTINCT FROM NEW.client_id THEN RETURN NEW; END IF; operation='edit'; END IF; END IF; IF TG_OP='UPDATE' AND NEW.data IS NOT DISTINCT FROM OLD.data AND NEW.client_id IS NOT DISTINCT FROM OLD.client_id THEN RETURN NEW; END IF; IF NOT public.gym_can_change(g,a,operation) THEN RAISE EXCEPTION 'You do not have permission to % this gym content',operation; END IF; RETURN coalesce(NEW,OLD); END $$;